{
  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "keep",
  "supportive_card_ids": ["C04", "C17", "C30", "C10", "C14", "C07", "C11", "C08", "C02"],
  "contradictory_card_ids": ["C18"],
  "prediction_basis_card_ids": ["C04", "C17", "C30", "C10", "C14", "C07", "C11", "C08", "C02"],
  "claims": [
    {
      "claim": "The query is a rigid N-methyl morphinan opioid (hydromorphone-like) with a phenolic C3 and basic amine; the closest visible measured opioid analogues, codeine, show absolute oral bioavailability of 80.5% in healthy subjects (C04) and relative oral bioavailability of 50.2% vs intramuscular dosing (C17, C30), both well above the 20% threshold.",
      "card_ids": ["C04", "C17", "C30"]
    },
    {
      "claim": "Additional opioid contexts visible in the prior records also report F above 20%: pethidine 0.80±0.15 in cirrhosis (C10, C14), pentazocine 0.68–0.70 in cirrhosis (C07, C11), meptazinol 27.9% in cirrhosis (C08), and naloxegol simulated F 0.90 (C02).",
      "card_ids": ["C10", "C14", "C07", "C11", "C08", "C02"]
    },
    {
      "claim": "The only visible low-F record is indacaterol in CD-1 mice (1%, C18), a non-opioid with low applicability to the query; it does not provide affirmative threshold-relevant evidence for hydromorphone F<20%.",
      "card_ids": ["C18"]
    },
    {
      "claim": "The L3 oral-exposure records (C31–C42) report ethinylestradiol Cmax/Cmin/Cτ values in oral contraceptive studies; they concern a different molecule and lack IV comparators, so they provide no direct evidence about hydromorphone absolute oral bioavailability.",
      "card_ids": ["C31", "C32", "C33", "C34", "C35", "C36", "C37", "C38", "C39", "C40", "C41", "C42"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "not_applicable",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C31", "C32", "C33", "C34", "C35", "C36", "C37", "C38", "C39", "C40", "C41", "C42"]
    }
  ],
  "evidence_gaps": [
    "No direct hydromorphone absolute oral bioavailability record is present in the visible set.",
    "L3 records are for ethinylestradiol, not the query, and Cmax/Cmin/Cτ without an IV comparator do not establish absolute F.",
    "Codeine relative bioavailability (C17, C30) is vs intramuscular, not intravenous, so it is not a pure absolute F value.",
    "Several opioid records are cirrhosis-conditioned; cirrhosis increases F by reducing first-pass metabolism, so exact healthy-subject transfer is uncertain (e.g., meptazinol 27.9% in cirrhosis is a four-fold increase over controls, C22).",
    "Naloxegol F 0.90 is a PBPK simulation (C02), not a measured clinical absolute F for the query scaffold.",
    "No dose-, formulation-, or prandial-state-matched hydromorphone data are available."
  ],
  "decision_summary": "L3 adds only ethinylestradiol oral-exposure records, which are not applicable to the hydromorphone query and do not change the prior high prediction. The high prediction remains supported by transferable opioid F records (codeine, pethidine, pentazocine, meptazinol, naloxegol), and no affirmative threshold-relevant evidence for F<20% is present."
}

